/** Filter options shown in the Shop sidebar, derived from the data so they never drift. */
export const SECTIONS = ["Men", "Women", "Kids"];
export const TYPES = ["Ethnic Wear", "Western Wear", "Casual Wear", "Formal Wear", "Activewear", "Winter Wear"];
export const BRANDS = [...new Set(PRODUCTS.map((p) => p.brand))].sort();

/** Look up one product by its numeric id (returns undefined when not found). */
export const getProductById = (id) => PRODUCTS.find((p) => p.id === Number(id));
